package com.graduation.gym.domain;import com.graduation.gym.auth.AuthService;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;@RestController@RequestMapping("/api/checkins")public class CheckInController{private final CheckInRepository repo;private final AuthService auth;public CheckInController(CheckInRepository r,AuthService a){repo=r;auth=a;}@PostMapping public CheckIn check(){var x=new CheckIn();x.setUserId(auth.currentUser().getId());x.setCheckInAt(LocalDateTime.now());x.setSource("FRONT_DESK");return repo.save(x);}@GetMapping public List<CheckIn>list(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?repo.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():repo.findTop200ByUserIdOrderByIdDesc(u.getId());}}